CustomField.formula:
IF(
    /* 両方に値がある場合 */
    AND(
        NOT(ISBLANK(Last_Bidding_Date_in_User_Storage__c)),
        NOT(ISBLANK(Last_Bidding_Date_in_Yard_Storage__c))
    ),
    /* (真) 日付が大きい方（新しい方）を取得 */
    IF(
        Last_Bidding_Date_in_User_Storage__c > Last_Bidding_Date_in_Yard_Storage__c,
        Last_Bidding_Date_in_User_Storage__c,
        Last_Bidding_Date_in_Yard_Storage__c
    ),
    /* (偽) どちらかが空なら、空でない方を採用（両方空なら空を返す） */
    BLANKVALUE(Last_Bidding_Date_in_User_Storage__c, Last_Bidding_Date_in_Yard_Storage__c)
)
